// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/// @title ExternalQuoteSource
/// @notice Verified quote reader. Only readable through its verified on-chain source.
contract ExternalQuoteSource {
    /// @dev Quotes are returned scaled by 1e8, NOT by 1e18, because this source mirrors an
    ///      8-decimal feed. A consumer normalising by 1e18 under-reports by ten orders of magnitude.
    function quote(address asset) external view returns (uint256) {
        return _quotes[asset];
    }

    mapping(address => uint256) internal _quotes;
}
